INSERT INTO `module_string` (`module`, `id`, `string`) VALUES
('mod-temucraft-threat', 1, '|cffc69b6dTank mode|r on: more threat, Taunt and less damage taken.'),
('mod-temucraft-threat', 2, '|cffc69b6dTank mode|r off.'),
('mod-temucraft-threat', 3, 'Tank mode is for Demonology warlocks, Enhancement shamans, Survival hunters and Combat rogues.'),
('mod-temucraft-threat', 4, 'Tank mode isn''t available on this server.'),
('mod-temucraft-threat', 5, 'Tank threat: |cff40ff40+{}%|r.'),
('mod-temucraft-threat', 6, 'Tank mode: on (Taunt, {}% less damage taken, more threat from your signature abilities).'),
('mod-temucraft-threat', 7, 'Healer threat: |cffff8040-{}%|r.'),
('mod-temucraft-threat', 8, 'No threat changes for your spec.'),
('mod-temucraft-threat', 9, 'Tank threat: only in Defensive Stance, Righteous Fury, Bear Form or Frost Presence.'),
('mod-temucraft-threat', 10, 'Tank role without a tank spec: |cffff8040{}% threat|r, 10% less health, armor and damage, 20% less maximum mana, rage and energy.'),
('mod-temucraft-threat', 11, 'Another player is your group''s tank: no tank threat bonus for you (.temucraft tankrole).'),
('mod-temucraft-threat', 12, 'Stand-in tank: |cff40ff40+{}% threat|r, Taunt, 1% more power regeneration, 10% less health, armor and damage.'),
('mod-temucraft-threat', 20, '|cffc69b6dTank:|r {} tanks in the group and {} place(s). Want it? .temucraft tankrole claim or .temucraft tankrole pass'),
('mod-temucraft-threat', 21, '|cffc69b6dTank:|r more players want to tank than there are places ({}). Vote with .temucraft tankrole vote <name>: {}.'),
('mod-temucraft-threat', 22, '|cffc69b6dTank:|r nobody in the group plays a tank spec. Stand in? .temucraft tankrole volunteer, or .temucraft tankrole pick <name>.'),
('mod-temucraft-threat', 23, '|cffc69b6dTank:|r {} picked you to stand in as tank. .temucraft tankrole accept or .temucraft tankrole decline'),
('mod-temucraft-threat', 24, '|cffc69b6dTank:|r {} is the group''s tank. Other tanks play without the tank threat bonus.'),
('mod-temucraft-threat', 25, '|cffc69b6dTank:|r {} stands in as tank (+threat and Taunt, 10% less health, armor and damage).'),
('mod-temucraft-threat', 26, '|cffc69b6dTank:|r nobody claimed the tank place: every tank keeps the bonus for now (.temucraft tankrole claim).'),
('mod-temucraft-threat', 27, '|cffc69b6dTank:|r nobody stands in as tank. Anyone can still: .temucraft tankrole volunteer'),
('mod-temucraft-threat', 28, '|cffc69b6dTank:|r a tank is in the group: the stand-in tank ends.'),
('mod-temucraft-threat', 29, '|cffc69b6dTank:|r asked {}.'),
('mod-temucraft-threat', 30, '|cffc69b6dTank:|r {} declined.'),
('mod-temucraft-threat', 31, '|cffc69b6dTank:|r not now (the group has a tank, or a question is open).'),
('mod-temucraft-threat', 32, '|cffc69b6dTank:|r noted.'),
('mod-temucraft-threat', 33, '|cffc69b6dTank:|r tank roles are for walk-in groups (the Dungeon Finder sets its own).'),
('mod-temucraft-threat', 34, '|cffc69b6dTank:|r you took the tank role without a tank spec (Not Playing Your Spec).'),
('mod-temucraft-threat', 35, '|cffc69b6dTank:|r .temucraft tankrole claim | pass | vote <name> | volunteer | pick <name> | accept | decline | stepdown | ask'),
('mod-temucraft-threat', 36, '|cffc69b6dTank:|r another player is your group''s tank.'),
('mod-temucraft-threat', 37, '|cffc69b6dTank:|r you stand in as your group''s tank (.temucraft tankrole stepdown to stop).'),
('mod-temucraft-threat', 38, '|cffc69b6dTank:|r the Dungeon Finder set your role.'),
('mod-temucraft-threat', 39, '|cffc69b6dTank:|r {} steps down as tank.'),
('mod-temucraft-threat', 40, '|cffc69b6dTank:|r no vote open for that name.'),
('mod-temucraft-threat', 41, '|cffc69b6dTank:|r the stand-in places are taken.'),
('mod-temucraft-threat', 42, '|cffc69b6dTank:|r your pick didn''t answer in time.');
